#!/usr/bin/env bash
#
# Benchmark script for the multi-method FEC × SBA bridge.
#
# Generated by validator stage of the /scope directive
#   Desktop/hq/directives/2026-05-15-fec-sba-bridge-multi-method.md
#
# Canonical invocation (from anywhere):
#
#   doppler run --project data-engine-x --config prd -- bash -c \
#     'apps/data-engine-x/scripts/benchmarks/fec_sba_bridge_multi_method.sh \
#        --lance-path /tmp/test_bridge_lance/'
#
# Reads R2_ENDPOINT, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY from env (Doppler).
# Compares the local rebuilt Lance dataset (or R2-path for live) against the
# success threshold + 9 constraints defined in the directive.
#
# Exit code 0 on all-pass, 1 otherwise.
#
# IMPORTANT FOR THE EXECUTOR:
# - The post-#456 Lance dataset already has a `match_method` column populated
#   with the string `'name_state_exact'`, NOT `'employer_eq_borrname'`. The
#   directive's constraint set assumes the new build relabels this to
#   `employer_eq_borrname`. The benchmark below queries the NEW label; if you
#   keep the legacy `name_state_exact` label, update the EXPECTED_LEGACY_METHOD
#   variable below to match (and the executor must document the choice in
#   `## Execution log`).

set -euo pipefail

LANCE_PATH=""
LIVE_R2_BASELINE="s3://dex-raw-landing-zone/polaris-warehouse/bridges/fec_sba_employer_lance/"
EXPECTED_LEGACY_METHOD="employer_eq_borrname"  # see comment above

while [[ $# -gt 0 ]]; do
  case "$1" in
    --lance-path)
      LANCE_PATH="$2"
      shift 2
      ;;
    --legacy-method-name)
      EXPECTED_LEGACY_METHOD="$2"
      shift 2
      ;;
    *)
      echo "Unknown arg: $1" >&2
      exit 2
      ;;
  esac
done

if [[ -z "$LANCE_PATH" ]]; then
  echo "Usage: $0 --lance-path /tmp/test_bridge_lance/ [--legacy-method-name <name>]" >&2
  exit 2
fi

# Use AWS-style env vars; DuckDB Lance extension's object_store crate doesn't
# recognise r2:// scheme (no provider). s3:// + AWS-style creds works against
# the same R2 endpoint.
export AWS_ENDPOINT_URL="${R2_ENDPOINT:?R2_ENDPOINT must be set}"
export AWS_ACCESS_KEY_ID="${R2_ACCESS_KEY_ID:?R2_ACCESS_KEY_ID must be set}"
export AWS_SECRET_ACCESS_KEY="${R2_SECRET_ACCESS_KEY:?R2_SECRET_ACCESS_KEY must be set}"
export AWS_REGION="auto"

PASS=1

duckdb_query() {
  duckdb -csv -noheader -c "INSTALL lance; LOAD lance; $1"
}

# --------------------------------------------------------------------------- #
# Constraint 1: schema is superset of post-#456 (no dropped columns).
# --------------------------------------------------------------------------- #
echo "C1: schema superset check…"
duckdb_query "SELECT column_name FROM (DESCRIBE SELECT * FROM __lance_scan('$LIVE_R2_BASELINE')) ORDER BY 1" \
  > /tmp/post_456_cols.txt
duckdb_query "SELECT column_name FROM (DESCRIBE SELECT * FROM __lance_scan('$LANCE_PATH')) ORDER BY 1" \
  > /tmp/new_cols.txt
DROPPED=$(comm -23 /tmp/post_456_cols.txt /tmp/new_cols.txt)
if [[ -n "$DROPPED" ]]; then
  echo "  FAIL: dropped columns: $DROPPED"
  PASS=0
else
  echo "  PASS"
fi

# --------------------------------------------------------------------------- #
# Constraint 2: `_normalize_entity_sql` unchanged (byte-identical).
# --------------------------------------------------------------------------- #
# Defer to git diff in the executor environment:
#   git -C ~/hq-all diff main -- apps/data-engine-x/scripts/build_bridge_fec_sba_employer.py \
#     | awk '/^def _normalize_entity_sql/,/^def /' \
#     | grep -E '^[+-]' \
#     | grep -v '^[+-]\{3\}'
# Output MUST be empty.
echo "C2: skipped here (run git diff externally)"

# --------------------------------------------------------------------------- #
# Constraint 3: each method contributes ≥ 1 row.
# --------------------------------------------------------------------------- #
echo "C3: each method ≥1 row…"
for m in employer_eq_borrname employer_eq_franchisename home_city_zip5_state_eq_business; do
  CNT=$(duckdb_query "SELECT COUNT(*) FROM __lance_scan('$LANCE_PATH') WHERE match_method = '$m'")
  if [[ "$CNT" -lt 1 ]]; then
    echo "  FAIL: $m → $CNT rows"
    PASS=0
  else
    echo "  PASS: $m → $CNT rows"
  fi
done

# --------------------------------------------------------------------------- #
# Constraint 4: no regression on brand canaries under employer_eq_borrname.
# Per-method floors carried forward from #456:
#   subway > 597, burger king > 136, 7-eleven > 102.
# --------------------------------------------------------------------------- #
echo "C4: brand canary floors (employer_eq_borrname)…"
read -r SUBWAY BK SEVEN <<< $(
  duckdb -csv -noheader -c "
    INSTALL lance; LOAD lance;
    SELECT
      COUNT(*) FILTER (WHERE match_value_normalized = 'subway'),
      COUNT(*) FILTER (WHERE match_value_normalized = 'burger king'),
      COUNT(*) FILTER (WHERE match_value_normalized = '7 eleven')
    FROM __lance_scan('$LANCE_PATH')
    WHERE match_method = 'employer_eq_borrname';
  " | tr ',' ' '
)
echo "  subway=$SUBWAY  burger king=$BK  7-eleven=$SEVEN"
[[ "${SUBWAY:-0}" -gt 597 ]] || { echo "    FAIL: subway $SUBWAY <= 597"; PASS=0; }
[[ "${BK:-0}" -gt 136 ]]     || { echo "    FAIL: burger king $BK <= 136"; PASS=0; }
[[ "${SEVEN:-0}" -gt 102 ]]  || { echo "    FAIL: 7 eleven $SEVEN <= 102"; PASS=0; }

# --------------------------------------------------------------------------- #
# Constraint 5: match_method is an enum of exactly {three values}.
# --------------------------------------------------------------------------- #
echo "C5: match_method enum check…"
duckdb_query "SELECT DISTINCT match_method FROM __lance_scan('$LANCE_PATH') ORDER BY 1" > /tmp/methods.txt
EXPECTED=$'employer_eq_borrname\nemployer_eq_franchisename\nhome_city_zip5_state_eq_business'
if ! diff -q <(echo "$EXPECTED") /tmp/methods.txt > /dev/null; then
  echo "  FAIL: expected {employer_eq_borrname, employer_eq_franchisename, home_city_zip5_state_eq_business}; got:"
  cat /tmp/methods.txt | sed 's/^/    /'
  PASS=0
else
  echo "  PASS"
fi

# --------------------------------------------------------------------------- #
# Constraint 6: confidence_tier values are documented (per-method semantics).
# Structural-only check: confirm only the 4 documented tier values appear.
# --------------------------------------------------------------------------- #
echo "C6: confidence_tier value-set check…"
duckdb_query "SELECT DISTINCT confidence_tier FROM __lance_scan('$LANCE_PATH') ORDER BY 1" > /tmp/tiers.txt
EXPECTED_TIERS=$'gold\nplatinum\nrejected\nsilver'
if ! diff -q <(echo "$EXPECTED_TIERS") /tmp/tiers.txt > /dev/null; then
  echo "  FAIL: tier values diverged:"
  cat /tmp/tiers.txt | sed 's/^/    /'
  PASS=0
else
  echo "  PASS"
fi

# --------------------------------------------------------------------------- #
# Constraint 7: tests stay green. Run externally:
#   cd apps/data-engine-x && doppler run -- uv run pytest tests/ -q
# Plus the canary tests called out in the directive.
# --------------------------------------------------------------------------- #
echo "C7: skipped here (run pytest externally)"

# --------------------------------------------------------------------------- #
# Constraint 8: ops.data_sources row unchanged. Run externally against ops db.
# Expected: display_name='fec_sba_employer_lance' | type='lance' | status='active'.
# --------------------------------------------------------------------------- #
echo "C8: skipped here (run ops.data_sources query externally)"

# --------------------------------------------------------------------------- #
# Constraint 9: structural — verified by code-review of --methods CLI arg in
# build_bridge_fec_sba_employer.py.
# --------------------------------------------------------------------------- #
echo "C9: skipped here (structural code-review constraint)"

# --------------------------------------------------------------------------- #
# Success threshold checks
# --------------------------------------------------------------------------- #
echo "--- success threshold ---"

TOTAL=$(duckdb_query "SELECT COUNT(*) FROM __lance_scan('$LANCE_PATH')")
echo "Total rows: $TOTAL (≥ 5,000,000)"
[[ "${TOTAL:-0}" -ge 5000000 ]] || { echo "  FAIL"; PASS=0; }

EQ_BORRNAME=$(duckdb_query "SELECT COUNT(*) FROM __lance_scan('$LANCE_PATH') WHERE match_method = 'employer_eq_borrname'")
echo "employer_eq_borrname rows: $EQ_BORRNAME (≥ 3,845,548)"
[[ "${EQ_BORRNAME:-0}" -ge 3845548 ]] || { echo "  FAIL"; PASS=0; }

EQ_FRANCHISE=$(duckdb_query "SELECT COUNT(*) FROM __lance_scan('$LANCE_PATH') WHERE match_method = 'employer_eq_franchisename'")
echo "employer_eq_franchisename rows: $EQ_FRANCHISE (≥ 50,000)"
[[ "${EQ_FRANCHISE:-0}" -ge 50000 ]] || { echo "  FAIL"; PASS=0; }

SUBWAY_FRANCHISE=$(duckdb_query "SELECT COUNT(*) FROM __lance_scan('$LANCE_PATH') WHERE match_method = 'employer_eq_franchisename' AND match_value_normalized = 'subway'")
echo "subway via employer_eq_franchisename: $SUBWAY_FRANCHISE (≥ 1)"
[[ "${SUBWAY_FRANCHISE:-0}" -ge 1 ]] || { echo "  FAIL"; PASS=0; }

HOME_ZIP5=$(duckdb_query "SELECT COUNT(*) FROM __lance_scan('$LANCE_PATH') WHERE match_method = 'home_city_zip5_state_eq_business'")
echo "home_city_zip5_state_eq_business rows: $HOME_ZIP5 (≥ 100,000)"
[[ "${HOME_ZIP5:-0}" -ge 100000 ]] || { echo "  FAIL"; PASS=0; }

# 2025-franchise canary: distinct loan_ids matched via ANY method
# uses /tmp/sba_franchise_full.csv (pre-staged, 2,295 rows)
if [[ -r /tmp/sba_franchise_full.csv ]]; then
  CANARY=$(duckdb -csv -noheader -c "
    INSTALL lance; LOAD lance;
    WITH franchise AS (
      SELECT lower(trim(borrname)) AS bn, upper(trim(borrstate)) AS bs
      FROM read_csv_auto('/tmp/sba_franchise_full.csv', header=true)
    )
    SELECT COUNT(DISTINCT b.loan_id)
    FROM __lance_scan('$LANCE_PATH') b
    JOIN franchise f
      ON b.match_value_normalized = f.bn AND b.match_state = f.bs
  ")
  echo "2025-franchise canary distinct loan_ids: $CANARY (≥ 400 across all methods)"
  [[ "${CANARY:-0}" -ge 400 ]] || { echo "  FAIL"; PASS=0; }
else
  echo "WARN: /tmp/sba_franchise_full.csv missing — canary check skipped"
fi

if [[ "$PASS" -eq 1 ]]; then
  echo "ALL PASS"
  exit 0
else
  echo "AT LEAST ONE CHECK FAILED"
  exit 1
fi
